// FIFO queue-aware order book implementation.
// Plan: .claude/plans/avellaneda-stoikov-mm-sim.md, step 1.
//
// Level totals are maintained alongside the per-level deques so top_of_book()
// reports the same aggregate share counts as OrderBookFlat (parity), while the
// deques preserve arrival order for the shadow order's queue-position model.

#include "order_book_queue.hpp"

#include <algorithm>
#include <stdexcept>

namespace itch {

namespace {
// A single shared empty queue so level_queue() can return a reference for
// vacant / out-of-range levels without allocating.
const std::deque<OrderBookQueue::QueueEntry> kEmptyQueue;
}  // namespace

OrderBookQueue::OrderBookQueue(uint32_t min_price_raw, uint32_t max_price_raw,
                               uint32_t tick_size)
    : min_price_(min_price_raw), max_price_(max_price_raw), tick_size_(tick_size) {
    if (max_price_raw <= min_price_raw)
        throw std::invalid_argument("max_price_raw must be > min_price_raw");
    if (tick_size == 0)
        throw std::invalid_argument("tick_size must be > 0");
    const std::size_t n = (max_price_raw - min_price_raw) / tick_size + 1;
    bid_q_.resize(n);
    ask_q_.resize(n);
    bid_tot_.assign(n, 0);
    ask_tot_.assign(n, 0);
}

std::size_t OrderBookQueue::index(uint32_t price_raw) const {
    if (price_raw < min_price_ || price_raw > max_price_) return INVALID;
    return (price_raw - min_price_) / tick_size_;
}

void OrderBookQueue::add(uint64_t order_ref, char side, uint32_t price_raw,
                         uint32_t shares) {
    if (loc_.count(order_ref)) { ++error_count_; return; }
    const std::size_t idx = index(price_raw);
    if (idx == INVALID) { ++error_count_; return; }
    loc_[order_ref] = {side, idx};
    if (side == 'B') {
        bid_q_[idx].push_back({order_ref, shares});
        bid_tot_[idx] += shares;
    } else {
        ask_q_[idx].push_back({order_ref, shares});
        ask_tot_[idx] += shares;
    }
}

uint32_t OrderBookQueue::execute(uint64_t order_ref, uint32_t executed_shares) {
    auto it = loc_.find(order_ref);
    if (it == loc_.end()) { ++error_count_; return 0; }
    const char side = it->second.side;
    const std::size_t idx = it->second.idx;
    std::deque<QueueEntry>& q = (side == 'B') ? bid_q_[idx] : ask_q_[idx];
    uint32_t& tot = (side == 'B') ? bid_tot_[idx] : ask_tot_[idx];

    for (auto qit = q.begin(); qit != q.end(); ++qit) {
        if (qit->order_ref != order_ref) continue;
        const uint32_t to_remove = std::min(executed_shares, qit->shares);
        qit->shares -= to_remove;
        tot -= to_remove;
        if (qit->shares == 0) {
            q.erase(qit);
            loc_.erase(it);
        }
        return to_remove;
    }
    // Locator pointed at a level with no matching entry — shouldn't happen.
    ++error_count_;
    return 0;
}

bool OrderBookQueue::del(uint64_t order_ref) {
    auto it = loc_.find(order_ref);
    if (it == loc_.end()) { ++error_count_; return false; }
    const char side = it->second.side;
    const std::size_t idx = it->second.idx;
    std::deque<QueueEntry>& q = (side == 'B') ? bid_q_[idx] : ask_q_[idx];
    uint32_t& tot = (side == 'B') ? bid_tot_[idx] : ask_tot_[idx];

    for (auto qit = q.begin(); qit != q.end(); ++qit) {
        if (qit->order_ref != order_ref) continue;
        tot -= qit->shares;
        q.erase(qit);
        loc_.erase(it);
        return true;
    }
    ++error_count_;
    return false;
}

void OrderBookQueue::replace(uint64_t old_ref, uint64_t new_ref, uint32_t shares,
                             uint32_t price_raw) {
    auto it = loc_.find(old_ref);
    if (it == loc_.end()) { ++error_count_; return; }
    const char side = it->second.side;
    del(old_ref);
    // Replace rejoins at the back of the new level's queue (loses priority) —
    // exactly the price-time cost the shadow model must see.
    add(new_ref, side, price_raw, shares);
}

TopOfBook OrderBookQueue::top_of_book() const {
    TopOfBook tob;
    for (std::size_t i = bid_tot_.size(); i-- > 0;) {
        if (bid_tot_[i] > 0) {
            tob.best_bid = PriceLevel{
                min_price_ + static_cast<uint32_t>(i) * tick_size_, bid_tot_[i]};
            break;
        }
    }
    for (std::size_t i = 0; i < ask_tot_.size(); ++i) {
        if (ask_tot_[i] > 0) {
            tob.best_ask = PriceLevel{
                min_price_ + static_cast<uint32_t>(i) * tick_size_, ask_tot_[i]};
            break;
        }
    }
    return tob;
}

const std::deque<OrderBookQueue::QueueEntry>& OrderBookQueue::level_queue(
    char side, uint32_t price_raw) const {
    const std::size_t idx = index(price_raw);
    if (idx == INVALID) return kEmptyQueue;
    return (side == 'B') ? bid_q_[idx] : ask_q_[idx];
}

uint32_t OrderBookQueue::level_shares(char side, uint32_t price_raw) const {
    const std::size_t idx = index(price_raw);
    if (idx == INVALID) return 0;
    return (side == 'B') ? bid_tot_[idx] : ask_tot_[idx];
}

bool OrderBookQueue::locate(uint64_t order_ref, char& side, uint32_t& price_raw,
                            uint32_t& shares) const {
    auto it = loc_.find(order_ref);
    if (it == loc_.end()) return false;
    side = it->second.side;
    const std::size_t idx = it->second.idx;
    price_raw = min_price_ + static_cast<uint32_t>(idx) * tick_size_;
    const std::deque<QueueEntry>& q = (side == 'B') ? bid_q_[idx] : ask_q_[idx];
    shares = 0;
    for (const QueueEntry& e : q) {
        if (e.order_ref == order_ref) {
            shares = e.shares;
            break;
        }
    }
    return true;
}

}  // namespace itch

