#pragma once
#include <cstdint>

// Shadow order: our simulated passive quote inside a real FIFO queue
// (SCAFFOLD). Plan: .claude/plans/avellaneda-stoikov-mm-sim.md, step 2.
//
// Placement snapshots the queue AHEAD (sum of real shares resting at the
// level at placement time). Thereafter, deterministically:
//   - an execution at the level consumes ahead-shares first; once ahead is
//     exhausted, further executed shares fill US (up to size) — shadow
//     no-impact assumption: the real order that traded still trades;
//   - a cancel/delete of a specific order AHEAD of us reduces ahead;
//     cancels behind us are irrelevant;
//   - requoting = cancel + new placement = rejoin at the BACK. Losing
//     queue position is a real, modeled cost.
//
// Implemented inline (small, hot, header-only like the flat book).

#include <algorithm>
#include <cstdint>

namespace itch {

struct ShadowFill {
    uint64_t timestamp_ns;
    char     side;          // 'B' or 'S'
    uint32_t price_raw;
    uint32_t shares;
};

class ShadowOrder {
public:
    ShadowOrder(char side, uint32_t price_raw, uint32_t size,
                uint64_t queue_ahead_shares)
        : side_(side),
          price_raw_(price_raw),
          remaining_(size),
          queue_ahead_(queue_ahead_shares) {}

    // A tape execution at our level. Under price-time FIFO, executed shares
    // consume the queue AHEAD of us first; only once that is exhausted do
    // further executed shares fill US (up to our remaining size). Returns the
    // shares WE fill on this execution. Shadow no-impact assumption: the real
    // order that traded still trades — we only ride its priority.
    uint32_t on_execution_at_level(uint32_t executed_shares) {
        if (remaining_ == 0) return 0;
        const uint64_t consumed_ahead =
            std::min<uint64_t>(queue_ahead_, executed_shares);
        queue_ahead_ -= consumed_ahead;
        const uint32_t into_us =
            static_cast<uint32_t>(executed_shares - consumed_ahead);
        const uint32_t fill = std::min(into_us, remaining_);
        remaining_ -= fill;
        return fill;
    }

    // A cancel/delete of shares belonging to an order AHEAD of us reduces the
    // queue ahead, promoting our position. Cancels behind us are irrelevant
    // and must not be routed here.
    void on_ahead_order_reduced(uint32_t canceled_shares) {
        const uint64_t reduced = std::min<uint64_t>(queue_ahead_, canceled_shares);
        queue_ahead_ -= reduced;
    }

    uint32_t remaining() const { return remaining_; }
    uint64_t queue_ahead() const { return queue_ahead_; }
    bool     filled() const { return remaining_ == 0; }
    char     side() const { return side_; }
    uint32_t price_raw() const { return price_raw_; }

private:
    char     side_;
    uint32_t price_raw_;
    uint32_t remaining_;
    uint64_t queue_ahead_;
};

}  // namespace itch

