// quotes both sides per the A-S closed form, and applies strategy actions
// through a tape-time-delayed pending queue (decision latency, default
// 1 ms). Fills come from ShadowOrder queue mechanics; PnL and inventory
// are recorded per decision point.
//
// A-S closed-form approximation (plan decision 4):
//   reservation r = m - q * gamma * sigma^2 * (T - t)
//   spread    delta = gamma * sigma^2 * (T - t) + (2/gamma) * ln(1 + gamma/kappa)
//   quotes at r +/- delta/2, tick-rounded, clamped inside the touch.
//
namespace itch {

// A tape-time-ordered queue of deferred actions modelling decision+action
// latency: an action decided at tape time t is pushed with effective time
// t + delay and only applied once the tape reaches that time. Tape timestamps
// are monotonic non-decreasing and the delay is fixed, so effective times are
// monotonic and a FIFO deque is sufficient. Exposed (header-only) so the
// latency-ordering contract can be unit-tested directly.
template <class Action>
class LatencyActionQueue {
public:
    void push(uint64_t effective_ns, Action action) {
        q_.push_back({effective_ns, std::move(action)});
    }

    // Apply, in FIFO order, every action whose effective time has arrived
    // (effective_ns <= now_ns). Nothing applies before its effective time.
    template <class Fn>
    void drain(uint64_t now_ns, Fn&& apply) {
        while (!q_.empty() && q_.front().effective_ns <= now_ns) {
            apply(q_.front().action);
            q_.pop_front();
        }
    }

    bool empty() const { return q_.empty(); }
    std::size_t size() const { return q_.size(); }

private:
    struct Item {
        uint64_t effective_ns;
        Action action;
    };
    std::deque<Item> q_;
};

struct MMParams {
    double   gamma = 1e-4;          // risk aversion
    double   kappa = 1.5;           // book liquidity parameter
    uint32_t quote_size = 100;      // shares per side
    int32_t  inventory_cap = 500;   // pull risk-increasing quote beyond this
    uint64_t latency_ns = 1'000'000;  // decision+action delay (1 ms default)
    uint64_t session_end_ns = 57'600'000'000'000;  // 16:00 ET
    uint32_t min_price_raw = 2'800'000;   // AAPL golden-day defaults
    uint32_t max_price_raw = 3'000'000;
};

struct MMSample {
    uint64_t timestamp_ns;
    double   mid;
    double   microprice;
    int32_t  inventory;
    double   cash;
    double   mark_to_mid_pnl;
    uint32_t bid_quote_raw;   // 0 when pulled
    uint32_t ask_quote_raw;   // 0 when pulled
};

// Desired A-S quotes for one decision, in ITCH fixed-point (raw) units.
struct ASQuote {
    double   reservation;   // r = m - q*gamma*sigma2*(T-t)
    double   half_spread;   // delta/2
    uint32_t bid_raw;       // tick-rounded, clamped inside the touch; 0 if pulled
    uint32_t ask_raw;       // 0 if pulled
    bool     bid_pulled;    // pulled by the inventory cap
    bool     ask_pulled;
    bool     clamped;       // a quote was clamped to avoid crossing the touch
};

// Pure Avellaneda-Stoikov closed-form quoter (plan decision 4). Exposed for
// unit testing the inventory-skew sign and spread behavior. All prices are in
// ITCH fixed-point (raw); sigma2 is the variance of the raw microprice and
// time_remaining is a unitless fraction of the session left in [0, 1].
// A quote is pulled when placing it would push inventory past the cap; a quote
// that would cross the touch is clamped one tick inside (pure passive).
ASQuote as_quote(double mid_raw, int32_t inventory, double sigma2,
                 double time_remaining, const MMParams& p,
                 uint32_t best_bid_raw, uint32_t best_ask_raw,
                 uint32_t tick_size = 1);

struct MMResult {
    std::vector<MMSample>   samples;
    std::vector<ShadowFill> fills;
    uint64_t requote_count      = 0;
    uint64_t clamped_quote_count = 0;
    uint64_t dropped_late_actions = 0;
    double   realized_pnl        = 0.0;   // spread capture, closed round-trips
    int32_t  terminal_inventory  = 0;
    double   terminal_mark       = 0.0;   // terminal inventory at final mid
};

class MMSimulator {
public:
    explicit MMSimulator(MMParams params);

    // Consume a full framed buffer (visitor-driven, max speed — no
    // ReplayClock dependency; composes with it later).
    MMResult run(const uint8_t* buf, std::size_t len);   // TODO(mm-4)

private:
    MMParams params_;
    // TODO(mm-4): OrderBookQueue, live ShadowOrders, pending-action queue,
    // rolling sigma^2 estimator (reuses microprice), accounting state.
};

