1	// Avellaneda-Stoikov market-making simulator implementation.
2	// Plan: .claude/plans/avellaneda-stoikov-mm-sim.md, steps 3-4.
3	//
4	// Event loop over a parsed ITCH stream: maintains the FIFO queue book, quotes
5	// both sides per the A-S closed form, defers quote actions through a fixed
6	// decision+action latency, and fills a shadow order by riding real trades'
7	// priority (no market impact). PnL is decomposed as net cash (realized) plus
8	// terminal inventory marked to the final mid.
9	
10	#include "mm_simulator.hpp"
11	#include "order_book.hpp"  // TopOfBook
12	
13	#include <algorithm>
14	#include <cmath>
15	#include <cstdint>
16	#include <optional>
17	#include <unordered_set>
18	
19	namespace itch {
20	
21	namespace {
22	constexpr double kRawToDollars = 1.0 / 10000.0;  // ITCH fixed-point -> $
23	constexpr uint64_t kSampleIntervalNs = 1'000'000'000ULL;  // 1 s between samples
24	
25	// Round a raw price down/up to the nearest tick multiple (absolute grid).
26	uint32_t round_to_tick(double px, uint32_t tick, bool up) {
27	    if (px <= 0.0) return 0;
28	    const double t = static_cast<double>(tick);
29	    const double n = up ? std::ceil(px / t) : std::floor(px / t);
30	    return static_cast<uint32_t>(n) * tick;
31	}
32	}  // namespace
33	
34	ASQuote as_quote(double mid_raw, int32_t inventory, double sigma2,
35	                 double time_remaining, const MMParams& p,
36	                 uint32_t best_bid_raw, uint32_t best_ask_raw,
37	                 uint32_t tick_size) {
38	    ASQuote out{};
39	    const double q = static_cast<double>(inventory);
40	
41	    // Reservation price and total spread (A-S closed-form approximation).
42	    out.reservation = mid_raw - q * p.gamma * sigma2 * time_remaining;
43	    const double delta = p.gamma * sigma2 * time_remaining +
44	                         (2.0 / p.gamma) * std::log(1.0 + p.gamma / p.kappa);
45	    out.half_spread = 0.5 * delta;
46	
47	    // Desired quotes, then round to ticks staying passive (bid down, ask up).
48	    uint32_t bid = round_to_tick(out.reservation - out.half_spread, tick_size, false);
49	    uint32_t ask = round_to_tick(out.reservation + out.half_spread, tick_size, true);
50	
51	    // Pure passive: never quote more aggressively than the touch. A desired
52	    // price inside the spread is clamped back to the touch (join the real
53	    // queue there); a desired price at or behind the touch rests deeper. This
54	    // is also what lets the shadow order ride real executions — it must sit at
55	    // a price where real orders actually trade. Inventory skew therefore moves
56	    // each side between "at the touch" (aggressive within passive limits) and
57	    // "resting deeper" (reluctant), never across the spread.
58	    if (best_bid_raw > 0 && bid > best_bid_raw) {
59	        bid = best_bid_raw;
60	        out.clamped = true;
61	    }
62	    if (ask < best_ask_raw) {
63	        ask = best_ask_raw;
64	        out.clamped = true;
65	    }
66	
67	    // Inventory cap: pull the risk-increasing side. Long past the cap -> stop
68	    // bidding (buying adds risk); short past the cap -> stop asking.
69	    if (inventory >= p.inventory_cap) {
70	        out.bid_pulled = true;
71	        bid = 0;
72	    }
73	    if (inventory <= -p.inventory_cap) {
74	        out.ask_pulled = true;
75	        ask = 0;
76	    }
77	
78	    out.bid_raw = bid;
79	    out.ask_raw = ask;
80	    return out;
81	}
82	
83	MMSimulator::MMSimulator(MMParams params) : params_(std::move(params)) {}
84	
85	MMResult MMSimulator::run(const uint8_t* buf, std::size_t len) {
86	    MMResult result;
87	    const MMParams& p = params_;
88	
89	    OrderBookQueue book(p.min_price_raw, p.max_price_raw);
90	
91	    // Shadow orders (at most one per side) plus the set of order refs that were
92	    // ahead of each at placement time (so cancels of ahead orders promote us,
93	    // while cancels of orders that arrived behind us are ignored).
94	    std::optional<ShadowOrder> bid_shadow, ask_shadow;
95	    std::unordered_set<uint64_t> bid_ahead, ask_ahead;
96	
97	    // A pending requote is a full re-placement of both sides.
98	    struct Requote {
99	        uint32_t bid_raw;  // 0 = pull the bid
100	        uint32_t ask_raw;  // 0 = pull the ask
101	    };
102	    LatencyActionQueue<Requote> pending;
103	
104	    int32_t inventory = 0;
105	    double cash = 0.0;
106	
107	    double sigma2 = 0.0;
108	    double last_microprice = 0.0;
109	    bool have_micro = false;
110	    double last_mid_raw = 0.0;  // final mid for terminal mark
111	
112	    uint32_t last_desired_bid = 0, last_desired_ask = 0;
113	    bool have_first_ts = false;
114	    uint64_t first_ts = 0;
115	    uint64_t last_sample_ns = 0;
116	
117	    auto apply_fill = [&](char side, uint32_t price_raw, uint32_t shares,
118	                          uint64_t ts) {
119	        const double dollars = static_cast<double>(shares) * price_raw * kRawToDollars;
120	        if (side == 'B') {  // our bid filled -> we bought
121	            inventory += static_cast<int32_t>(shares);
122	            cash -= dollars;
123	        } else {  // our ask filled -> we sold
124	            inventory -= static_cast<int32_t>(shares);
125	            cash += dollars;
126	        }
127	        result.fills.push_back({ts, side, price_raw, shares});
128	    };
129	
130	    auto place = [&](std::optional<ShadowOrder>& shadow,
131	                     std::unordered_set<uint64_t>& ahead, char side,
132	                     uint32_t price_raw) {
133	        if (price_raw == 0) {
134	            shadow.reset();
135	            ahead.clear();
136	            return;
137	        }
138	        const uint32_t ahead_shares = book.level_shares(side, price_raw);
139	        shadow.emplace(side, price_raw, p.quote_size, ahead_shares);
140	        ahead.clear();
141	        for (const auto& e : book.level_queue(side, price_raw))
142	            ahead.insert(e.order_ref);
143	    };
144	
145	    auto apply_requote = [&](const Requote& rq) {
146	        ++result.requote_count;
147	        place(bid_shadow, bid_ahead, 'B', rq.bid_raw);
148	        place(ask_shadow, ask_ahead, 'S', rq.ask_raw);
149	    };
150	
151	    // Flush any latency-deferred actions whose effective time has arrived.
152	    auto flush = [&](uint64_t ts) {
153	        pending.drain(ts, apply_requote);
154	    };
155	
156	    // A cancel/delete/replace removed `shares` of order `ref` at (side, price);
157	    // if that order was ahead of our shadow, it promotes us.
158	    auto reduce_ahead = [&](char side, uint32_t price_raw, uint64_t ref,
159	                            uint32_t shares, bool full_removal) {
160	        if (bid_shadow && side == 'B' && price_raw == bid_shadow->price_raw() &&
161	            bid_ahead.count(ref)) {
162	            bid_shadow->on_ahead_order_reduced(shares);
163	            if (full_removal) bid_ahead.erase(ref);
164	        }
165	        if (ask_shadow && side == 'S' && price_raw == ask_shadow->price_raw() &&
166	            ask_ahead.count(ref)) {
167	            ask_shadow->on_ahead_order_reduced(shares);
168	            if (full_removal) ask_ahead.erase(ref);
169	        }
170	    };
171	
172	    // After each event: update volatility, decide quotes, defer the action,
173	    // and record a decimated sample.
174	    auto post = [&](uint64_t ts) {
175	        const TopOfBook tob = book.top_of_book();
176	        if (!tob.best_bid || !tob.best_ask) return;  // need a two-sided market
177	        const uint32_t bb = tob.best_bid->price_raw;
178	        const uint32_t ba = tob.best_ask->price_raw;
179	        const uint32_t bsz = tob.best_bid->shares;
180	        const uint32_t asz = tob.best_ask->shares;
181	        const double mid = 0.5 * (static_cast<double>(bb) + ba);
182	        const double micro =
183	            (static_cast<double>(bb) * asz + static_cast<double>(ba) * bsz) /
184	            (static_cast<double>(bsz) + asz);
185	        last_mid_raw = mid;
186	
187	        if (have_micro) {
188	            const double dret = micro - last_microprice;
189	            sigma2 = 0.99 * sigma2 + 0.01 * dret * dret;  // EWMA of squared move
190	        }
191	        last_microprice = micro;
192	        have_micro = true;
193	
194	        double time_frac = 0.0;
195	        if (p.session_end_ns > first_ts && ts < p.session_end_ns)
196	            time_frac = static_cast<double>(p.session_end_ns - ts) /
197	                        static_cast<double>(p.session_end_ns - first_ts);
198	
199	        const ASQuote qd =
200	            as_quote(mid, inventory, sigma2, time_frac, p, bb, ba);
201	
202	        // Enqueue a requote only when the tick-rounded target actually changes,
203	        // so requote_count reflects real quote churn, not every event.
204	        if (qd.bid_raw != last_desired_bid || qd.ask_raw != last_desired_ask) {
205	            const uint64_t effective = ts + p.latency_ns;
206	            if (effective > p.session_end_ns) {
207	                ++result.dropped_late_actions;
208	            } else {
209	                pending.push(effective, Requote{qd.bid_raw, qd.ask_raw});
210	            }
211	            if (qd.clamped) ++result.clamped_quote_count;
212	            last_desired_bid = qd.bid_raw;
213	            last_desired_ask = qd.ask_raw;
214	        }
215	
216	        if (ts - last_sample_ns >= kSampleIntervalNs || result.samples.empty()) {
217	            const double mark = cash + inventory * mid * kRawToDollars;
218	            result.samples.push_back(MMSample{
219	                ts, mid * kRawToDollars, micro * kRawToDollars, inventory, cash,
220	                mark, bid_shadow ? bid_shadow->price_raw() : 0,
221	                ask_shadow ? ask_shadow->price_raw() : 0});
222	            last_sample_ns = ts;
223	        }
224	    };
225	
226	    // Common per-event prologue: remember the session origin and apply any
227	    // latency-deferred actions that are now due.
228	    auto pre = [&](uint64_t ts) {
229	        if (!have_first_ts) {
230	            first_ts = ts;
231	            last_sample_ns = ts;
232	            have_first_ts = true;
233	        }
234	        flush(ts);
235	    };
236	
237	    MessageVisitor visitor;
238	    visitor.on_add = [&](const AddOrder& a) {
239	        pre(a.timestamp_ns);
240	        book.add(a.order_ref, a.side, a.price, a.shares);
241	        post(a.timestamp_ns);
242	    };
243	    visitor.on_execute = [&](const ExecuteOrder& e) {
244	        pre(e.timestamp_ns);
245	        char s;
246	        uint32_t px, sh;
247	        if (book.locate(e.order_ref, s, px, sh)) {
248	            const uint32_t removed = std::min(e.executed_shares, sh);
249	            if (bid_shadow && s == 'B' && px == bid_shadow->price_raw()) {
250	                const uint32_t fill = bid_shadow->on_execution_at_level(removed);
251	                if (fill) apply_fill('B', bid_shadow->price_raw(), fill, e.timestamp_ns);
252	            }
253	            if (ask_shadow && s == 'S' && px == ask_shadow->price_raw()) {
254	                const uint32_t fill = ask_shadow->on_execution_at_level(removed);
255	                if (fill) apply_fill('S', ask_shadow->price_raw(), fill, e.timestamp_ns);
256	            }
257	        }
258	        book.execute(e.order_ref, e.executed_shares);
259	        post(e.timestamp_ns);
260	    };
261	    visitor.on_cancel = [&](const CancelOrder& c) {
262	        pre(c.timestamp_ns);
263	        char s;
264	        uint32_t px, sh;
265	        if (book.locate(c.order_ref, s, px, sh))
266	            reduce_ahead(s, px, c.order_ref, c.canceled_shares, /*full=*/false);
267	        book.execute(c.order_ref, c.canceled_shares);  // 'X' removes shares
268	        post(c.timestamp_ns);
269	    };
270	    visitor.on_delete = [&](const DeleteOrder& d) {
271	        pre(d.timestamp_ns);
272	        char s;
273	        uint32_t px, sh;
274	        if (book.locate(d.order_ref, s, px, sh))
275	            reduce_ahead(s, px, d.order_ref, sh, /*full=*/true);
276	        book.del(d.order_ref);
277	        post(d.timestamp_ns);
278	    };
279	    visitor.on_replace = [&](const ReplaceOrder& r) {
280	        pre(r.timestamp_ns);
281	        char s;
282	        uint32_t px, sh;
283	        if (book.locate(r.old_order_ref, s, px, sh))
284	            reduce_ahead(s, px, r.old_order_ref, sh, /*full=*/true);
285	        book.replace(r.old_order_ref, r.new_order_ref, r.shares, r.price);
286	        post(r.timestamp_ns);
287	    };
288	
289	    parse_buffer(buf, len, visitor);
290	
291	    result.realized_pnl = cash;  // net cash = realized round-trip PnL
292	    result.terminal_inventory = inventory;
293	    result.terminal_mark = inventory * last_mid_raw * kRawToDollars;
294	
295	    // Record a final sample at the terminal state so samples.back() reflects
296	    // end-of-session cash/inventory (decimation can otherwise leave the last
297	    // sample stale). This makes realized_pnl + terminal_mark == the final
298	    // sample's mark-to-mid PnL exactly.
299	    if (have_micro && !result.samples.empty()) {
300	        const uint64_t last_ts = result.samples.back().timestamp_ns;
301	        result.samples.push_back(MMSample{
302	            last_ts, last_mid_raw * kRawToDollars, last_microprice * kRawToDollars,
303	            inventory, cash, cash + inventory * last_mid_raw * kRawToDollars,
304	            bid_shadow ? bid_shadow->price_raw() : 0,
305	            ask_shadow ? ask_shadow->price_raw() : 0});
306	    }
307	    return result;
308	}
309	
310	}  // namespace itch
