// Avellaneda-Stoikov market-making simulator implementation.
// Plan: .claude/plans/avellaneda-stoikov-mm-sim.md, steps 3-4.
//
// Event loop over a parsed ITCH stream: maintains the FIFO queue book, quotes
// both sides per the A-S closed form, defers quote actions through a fixed
// decision+action latency, and fills a shadow order by riding real trades'
// priority (no market impact). PnL is decomposed as net cash (realized) plus
// terminal inventory marked to the final mid.

#include "mm_simulator.hpp"
#include "order_book.hpp"  // TopOfBook

#include <algorithm>
#include <cmath>
#include <cstdint>
#include <optional>
#include <unordered_set>

namespace itch {

namespace {
constexpr double kRawToDollars = 1.0 / 10000.0;  // ITCH fixed-point -> $
constexpr uint64_t kSampleIntervalNs = 1'000'000'000ULL;  // 1 s between samples

// Round a raw price down/up to the nearest tick multiple (absolute grid).
uint32_t round_to_tick(double px, uint32_t tick, bool up) {
    if (px <= 0.0) return 0;
    const double t = static_cast<double>(tick);
    const double n = up ? std::ceil(px / t) : std::floor(px / t);
    return static_cast<uint32_t>(n) * tick;
}
}  // namespace

ASQuote as_quote(double mid_raw, int32_t inventory, double sigma2,
                 double time_remaining, const MMParams& p,
                 uint32_t best_bid_raw, uint32_t best_ask_raw,
                 uint32_t tick_size) {
    ASQuote out{};
    const double q = static_cast<double>(inventory);

    // Reservation price and total spread (A-S closed-form approximation).
    out.reservation = mid_raw - q * p.gamma * sigma2 * time_remaining;
    const double delta = p.gamma * sigma2 * time_remaining +
                         (2.0 / p.gamma) * std::log(1.0 + p.gamma / p.kappa);
    out.half_spread = 0.5 * delta;

    // Desired quotes, then round to ticks staying passive (bid down, ask up).
    uint32_t bid = round_to_tick(out.reservation - out.half_spread, tick_size, false);
    uint32_t ask = round_to_tick(out.reservation + out.half_spread, tick_size, true);

    // Pure passive: never quote more aggressively than the touch. A desired
    // price inside the spread is clamped back to the touch (join the real
    // queue there); a desired price at or behind the touch rests deeper. This
    // is also what lets the shadow order ride real executions — it must sit at
    // a price where real orders actually trade. Inventory skew therefore moves
    // each side between "at the touch" (aggressive within passive limits) and
    // "resting deeper" (reluctant), never across the spread.
    if (best_bid_raw > 0 && bid > best_bid_raw) {
        bid = best_bid_raw;
        out.clamped = true;
    }
    if (ask < best_ask_raw) {
        ask = best_ask_raw;
        out.clamped = true;
    }

    // Inventory cap: pull the risk-increasing side. Long past the cap -> stop
    // bidding (buying adds risk); short past the cap -> stop asking.
    if (inventory >= p.inventory_cap) {
        out.bid_pulled = true;
        bid = 0;
    }
    if (inventory <= -p.inventory_cap) {
        out.ask_pulled = true;
        ask = 0;
    }

    out.bid_raw = bid;
    out.ask_raw = ask;
    return out;
}

MMSimulator::MMSimulator(MMParams params) : params_(std::move(params)) {}

MMResult MMSimulator::run(const uint8_t* buf, std::size_t len) {
    MMResult result;
    const MMParams& p = params_;

    OrderBookQueue book(p.min_price_raw, p.max_price_raw);

    // Shadow orders (at most one per side) plus the set of order refs that were
    // ahead of each at placement time (so cancels of ahead orders promote us,
    // while cancels of orders that arrived behind us are ignored).
    std::optional<ShadowOrder> bid_shadow, ask_shadow;
    std::unordered_set<uint64_t> bid_ahead, ask_ahead;

    // A pending requote is a full re-placement of both sides.
    struct Requote {
        uint32_t bid_raw;  // 0 = pull the bid
        uint32_t ask_raw;  // 0 = pull the ask
    };
    LatencyActionQueue<Requote> pending;

    int32_t inventory = 0;
    double cash = 0.0;

    double sigma2 = 0.0;
    double last_microprice = 0.0;
    bool have_micro = false;
    double last_mid_raw = 0.0;  // final mid for terminal mark

    uint32_t last_desired_bid = 0, last_desired_ask = 0;
    bool have_first_ts = false;
    uint64_t first_ts = 0;
    uint64_t last_sample_ns = 0;

    auto apply_fill = [&](char side, uint32_t price_raw, uint32_t shares,
                          uint64_t ts) {
        const double dollars = static_cast<double>(shares) * price_raw * kRawToDollars;
        if (side == 'B') {  // our bid filled -> we bought
            inventory += static_cast<int32_t>(shares);
            cash -= dollars;
        } else {  // our ask filled -> we sold
            inventory -= static_cast<int32_t>(shares);
            cash += dollars;
        }
        result.fills.push_back({ts, side, price_raw, shares});
    };

    auto place = [&](std::optional<ShadowOrder>& shadow,
                     std::unordered_set<uint64_t>& ahead, char side,
                     uint32_t price_raw) {
        if (price_raw == 0) {
            shadow.reset();
            ahead.clear();
            return;
        }
        const uint32_t ahead_shares = book.level_shares(side, price_raw);
        shadow.emplace(side, price_raw, p.quote_size, ahead_shares);
        ahead.clear();
        for (const auto& e : book.level_queue(side, price_raw))
            ahead.insert(e.order_ref);
    };

    auto apply_requote = [&](const Requote& rq) {
        ++result.requote_count;
        place(bid_shadow, bid_ahead, 'B', rq.bid_raw);
        place(ask_shadow, ask_ahead, 'S', rq.ask_raw);
    };

    // Flush any latency-deferred actions whose effective time has arrived.
    auto flush = [&](uint64_t ts) {
        pending.drain(ts, apply_requote);
    };

    // A cancel/delete/replace removed `shares` of order `ref` at (side, price);
    // if that order was ahead of our shadow, it promotes us.
    auto reduce_ahead = [&](char side, uint32_t price_raw, uint64_t ref,
                            uint32_t shares, bool full_removal) {
        if (bid_shadow && side == 'B' && price_raw == bid_shadow->price_raw() &&
            bid_ahead.count(ref)) {
            bid_shadow->on_ahead_order_reduced(shares);
            if (full_removal) bid_ahead.erase(ref);
        }
        if (ask_shadow && side == 'S' && price_raw == ask_shadow->price_raw() &&
            ask_ahead.count(ref)) {
            ask_shadow->on_ahead_order_reduced(shares);
            if (full_removal) ask_ahead.erase(ref);
        }
    };

    // After each event: update volatility, decide quotes, defer the action,
    // and record a decimated sample.
    auto post = [&](uint64_t ts) {
        const TopOfBook tob = book.top_of_book();
        if (!tob.best_bid || !tob.best_ask) return;  // need a two-sided market
        const uint32_t bb = tob.best_bid->price_raw;
        const uint32_t ba = tob.best_ask->price_raw;
        const uint32_t bsz = tob.best_bid->shares;
        const uint32_t asz = tob.best_ask->shares;
        const double mid = 0.5 * (static_cast<double>(bb) + ba);
        const double micro =
            (static_cast<double>(bb) * asz + static_cast<double>(ba) * bsz) /
            (static_cast<double>(bsz) + asz);
        last_mid_raw = mid;

        if (have_micro) {
            const double dret = micro - last_microprice;
            sigma2 = 0.99 * sigma2 + 0.01 * dret * dret;  // EWMA of squared move
        }
        last_microprice = micro;
        have_micro = true;

        double time_frac = 0.0;
        if (p.session_end_ns > first_ts && ts < p.session_end_ns)
            time_frac = static_cast<double>(p.session_end_ns - ts) /
                        static_cast<double>(p.session_end_ns - first_ts);

        const ASQuote qd =
            as_quote(mid, inventory, sigma2, time_frac, p, bb, ba);

        // Enqueue a requote only when the tick-rounded target actually changes,
        // so requote_count reflects real quote churn, not every event.
        if (qd.bid_raw != last_desired_bid || qd.ask_raw != last_desired_ask) {
            const uint64_t effective = ts + p.latency_ns;
            if (effective > p.session_end_ns) {
                ++result.dropped_late_actions;
            } else {
                pending.push(effective, Requote{qd.bid_raw, qd.ask_raw});
            }
            if (qd.clamped) ++result.clamped_quote_count;
            last_desired_bid = qd.bid_raw;
            last_desired_ask = qd.ask_raw;
        }

        if (ts - last_sample_ns >= kSampleIntervalNs || result.samples.empty()) {
            const double mark = cash + inventory * mid * kRawToDollars;
            result.samples.push_back(MMSample{
                ts, mid * kRawToDollars, micro * kRawToDollars, inventory, cash,
                mark, bid_shadow ? bid_shadow->price_raw() : 0,
                ask_shadow ? ask_shadow->price_raw() : 0});
            last_sample_ns = ts;
        }
    };

    // Common per-event prologue: remember the session origin and apply any
    // latency-deferred actions that are now due.
    auto pre = [&](uint64_t ts) {
        if (!have_first_ts) {
            first_ts = ts;
            last_sample_ns = ts;
            have_first_ts = true;
        }
        flush(ts);
    };

    MessageVisitor visitor;
    visitor.on_add = [&](const AddOrder& a) {
        pre(a.timestamp_ns);
        book.add(a.order_ref, a.side, a.price, a.shares);
        post(a.timestamp_ns);
    };
    visitor.on_execute = [&](const ExecuteOrder& e) {
        pre(e.timestamp_ns);
        char s;
        uint32_t px, sh;
        if (book.locate(e.order_ref, s, px, sh)) {
            const uint32_t removed = std::min(e.executed_shares, sh);
            if (bid_shadow && s == 'B' && px == bid_shadow->price_raw()) {
                const uint32_t fill = bid_shadow->on_execution_at_level(removed);
                if (fill) apply_fill('B', bid_shadow->price_raw(), fill, e.timestamp_ns);
            }
            if (ask_shadow && s == 'S' && px == ask_shadow->price_raw()) {
                const uint32_t fill = ask_shadow->on_execution_at_level(removed);
                if (fill) apply_fill('S', ask_shadow->price_raw(), fill, e.timestamp_ns);
            }
        }
        book.execute(e.order_ref, e.executed_shares);
        post(e.timestamp_ns);
    };
    visitor.on_cancel = [&](const CancelOrder& c) {
        pre(c.timestamp_ns);
        char s;
        uint32_t px, sh;
        if (book.locate(c.order_ref, s, px, sh))
            reduce_ahead(s, px, c.order_ref, c.canceled_shares, /*full=*/false);
        book.execute(c.order_ref, c.canceled_shares);  // 'X' removes shares
        post(c.timestamp_ns);
    };
    visitor.on_delete = [&](const DeleteOrder& d) {
        pre(d.timestamp_ns);
        char s;
        uint32_t px, sh;
        if (book.locate(d.order_ref, s, px, sh))
            reduce_ahead(s, px, d.order_ref, sh, /*full=*/true);
        book.del(d.order_ref);
        post(d.timestamp_ns);
    };
    visitor.on_replace = [&](const ReplaceOrder& r) {
        pre(r.timestamp_ns);
        char s;
        uint32_t px, sh;
        if (book.locate(r.old_order_ref, s, px, sh))
            reduce_ahead(s, px, r.old_order_ref, sh, /*full=*/true);
        book.replace(r.old_order_ref, r.new_order_ref, r.shares, r.price);
        post(r.timestamp_ns);
    };

    parse_buffer(buf, len, visitor);

    result.realized_pnl = cash;  // net cash = realized round-trip PnL
    result.terminal_inventory = inventory;
    result.terminal_mark = inventory * last_mid_raw * kRawToDollars;

    // Record a final sample at the terminal state so samples.back() reflects
    // end-of-session cash/inventory (decimation can otherwise leave the last
    // sample stale). This makes realized_pnl + terminal_mark == the final
    // sample's mark-to-mid PnL exactly.
    if (have_micro && !result.samples.empty()) {
        const uint64_t last_ts = result.samples.back().timestamp_ns;
        result.samples.push_back(MMSample{
            last_ts, last_mid_raw * kRawToDollars, last_microprice * kRawToDollars,
            inventory, cash, cash + inventory * last_mid_raw * kRawToDollars,
            bid_shadow ? bid_shadow->price_raw() : 0,
            ask_shadow ? ask_shadow->price_raw() : 0});
    }
    return result;
}

}  // namespace itch

