1	// pybind11 bridge: microstructure signal stream -> Python.
2	// Plan: .claude/plans/microstructure-signals.md, step 4.
3	//
4	// events_from_file() parses a symbol-filtered framed ITCH 5.0 file with
5	// MicrostructureEngine and returns the event stream as COLUMNAR lists —
6	// one list per MicroEvent field rather than one Python object per event.
7	// The filtered AAPL golden day has ~1.5M messages; a struct-of-arrays dict
8	// crosses the boundary as 7 list conversions instead of millions of tiny
9	// object allocations, and feeds pd.DataFrame(result) directly.
10	//
11	// The file is read in one gulp: symbol-filtered days are ~45 MB. Do NOT
12	// hand this function the unfiltered multi-GB exchange day — filter first
13	// with scripts/fetch_itch_sample.sh / itch_filter.
14	
15	#include <pybind11/pybind11.h>
16	#include <pybind11/stl.h>
17	
18	#include "microstructure_signals.hpp"
19	#include "mm_simulator.hpp"
20	
21	#include <cstdio>
22	#include <memory>
23	#include <stdexcept>
24	#include <string>
25	#include <vector>
26	
27	namespace py = pybind11;
28	
29	namespace {
30	
