+                   uint32_t shares) {
+    const std::size_t s = begin_msg(buf, 31, 'E', ts);  // SIZE_EXECUTE_ORDER
+    put_be(buf, s + 11, ref, 8);
+    put_be(buf, s + 19, shares, 4);
