+void put_be(std::vector<uint8_t>& b, std::size_t off, uint64_t v, int n) {
+    for (int i = 0; i < n; ++i)
+        b[off + i] = static_cast<uint8_t>((v >> (8 * (n - 1 - i))) & 0xFF);
+}
+
+// Append a framed ITCH message: 2-byte BE length + body of body_len bytes.
+// Returns the body's start offset so the caller can fill type-specific fields.
+std::size_t begin_msg(std::vector<uint8_t>& buf, uint16_t body_len, char type,
+                      uint64_t ts) {
+    buf.push_back(static_cast<uint8_t>(body_len >> 8));
+    buf.push_back(static_cast<uint8_t>(body_len & 0xFF));
+    const std::size_t start = buf.size();
+    buf.resize(start + body_len, 0);
+    buf[start] = static_cast<uint8_t>(type);
+    put_be(buf, start + 5, ts, 6);  // timestamp at offset 5
+    return start;
