1	#pragma once
2	#include <cstdint>
3	#include <cstddef>
4	#include <functional>
5	#include <string>
6	
7	// Nasdaq TotalView-ITCH 5.0 message subset needed for limit-order-book
8	// reconstruction.  Only Add / Delete / Replace / Execute are parsed;
9	// all other message types are skipped without reading past the buffer.
10	//
11	// All multi-byte fields in ITCH are big-endian.
12	
13	namespace itch {
14	
15	// ─── Message types (ITCH 5.0 §4) ────────────────────────────────────────────
16	
17	enum class MsgType : char {
18	    AddOrder           = 'A',
19	    AddOrderMPID       = 'F',
20	    ExecuteOrder       = 'E',
21	    ExecuteOrderPrice  = 'C',
22	    CancelOrder        = 'X',
23	    DeleteOrder        = 'D',
24	    ReplaceOrder       = 'U',
25	    // All other types are skipped.
26	    Unknown            = '\0',
27	};
28	
29	// ─── Parsed message structs ──────────────────────────────────────────────────
30	
31	// All messages carry the ITCH timestamp: nanoseconds since midnight (ET),
32	// 6 bytes big-endian on the wire, widened to uint64_t here.
33	
34	struct AddOrder {
35	    uint64_t timestamp_ns;
36	    uint64_t order_ref;
37	    char     side;          // 'B' or 'S'
38	    uint32_t shares;
39	    uint32_t price;         // price * 10000 (ITCH fixed-point 4 decimals)
40	};
41	
42	struct ExecuteOrder {
43	    uint64_t timestamp_ns;
44	    uint64_t order_ref;
45	    uint32_t executed_shares;
46	};
47	
48	// Partial cancel ('X'): removes canceled_shares from a resting order.
49	// Full removals arrive as DeleteOrder ('D'). Skipping 'X' leaves phantom
50	// depth in a reconstructed book — a resting order whose remainder was
51	// canceled appears live forever (observed on the real AAPL golden day as a
52	// permanently crossed top-of-book).
53	struct CancelOrder {
54	    uint64_t timestamp_ns;
55	    uint64_t order_ref;
56	    uint32_t canceled_shares;
57	};
58	
59	struct DeleteOrder {
60	    uint64_t timestamp_ns;
61	    uint64_t order_ref;
62	};
63	
64	struct ReplaceOrder {
