#include "../../HFT_Trading_Practice_Repo/cpp/itch/mm_simulator.hpp"
#include <cstdio>
#include <vector>
#include <cstdint>

using namespace itch;

namespace {
void put_be(std::vector<uint8_t>& b, std::size_t off, uint64_t v, int n) {
    for (int i = 0; i < n; ++i)
        b[off + i] = static_cast<uint8_t>((v >> (8 * (n - 1 - i))) & 0xFF);
}
std::size_t begin_msg(std::vector<uint8_t>& buf, uint16_t body_len, char type, uint64_t ts) {
    buf.push_back(static_cast<uint8_t>(body_len >> 8));
    buf.push_back(static_cast<uint8_t>(body_len & 0xFF));
    const std::size_t start = buf.size();
    buf.resize(start + body_len, 0);
    buf[start] = static_cast<uint8_t>(type);
    put_be(buf, start + 5, ts, 6);
    return start;
}
void add_order(std::vector<uint8_t>& buf, uint64_t ts, uint64_t ref, char side, uint32_t shares, uint32_t price) {
    const std::size_t s = begin_msg(buf, 36, 'A', ts);
    put_be(buf, s + 11, ref, 8);
    buf[s + 19] = static_cast<uint8_t>(side);
    put_be(buf, s + 20, shares, 4);
    put_be(buf, s + 32, price, 4);
}
void execute_order(std::vector<uint8_t>& buf, uint64_t ts, uint64_t ref, uint32_t shares) {
    const std::size_t s = begin_msg(buf, 31, 'E', ts);
    put_be(buf, s + 11, ref, 8);
    put_be(buf, s + 19, shares, 4);
}
}

int main() {
    std::vector<uint8_t> buf;
    uint64_t ts = 34'200'000'000'000ULL;
    const uint64_t step = 5'000'000ULL;

    add_order(buf, ts += step, 1, 'B', 200, 2'899'900);
    add_order(buf, ts += step, 2, 'S', 200, 2'900'100);
    add_order(buf, ts += step, 3, 'B', 50,  2'899'800);
    add_order(buf, ts += step, 4, 'B', 80,  2'899'900);  // arrives AFTER our bid shadow placed
    execute_order(buf, ts += step, 1, 150);
    execute_order(buf, ts += step, 1, 50);   // ref1 fully cleared, ahead exhausted
    execute_order(buf, ts += step, 4, 30);   // should fill OUR shadow bid (ahead=0) by 30
    // now trigger an ASK-only quote change: improve best ask, bid target unchanged
    add_order(buf, ts += step, 5, 'S', 500, 2'900'050);
    add_order(buf, ts += step, 6, 'B', 10,  2'899'700);  // filler event to flush pending requote
    // Now try to fill the bid shadow AGAIN beyond its original quote_size (100)
    // via ref4's remaining shares (80-30=50 left) plus new resting ref7.
    add_order(buf, ts += step, 7, 'B', 100, 2'899'900);  // arrives after shadow re-placement -> behind
    execute_order(buf, ts += step, 4, 50);   // finish off ref4's remaining 50 -> should reach ahead=0 again if shadow got reset
    execute_order(buf, ts += step, 7, 100);  // if shadow reset, this fills us AGAIN beyond original 100 cap

    MMParams p;
    p.latency_ns = 0;
    p.quote_size = 100;
    MMSimulator sim(p);
    MMResult r = sim.run(buf.data(), buf.size());

    printf("requote_count=%llu fills=%zu terminal_inventory=%d\n",
           (unsigned long long)r.requote_count, r.fills.size(), r.terminal_inventory);
    uint32_t total_bid_fill_shares = 0;
    for (auto& f : r.fills) {
        printf("fill ts=%llu side=%c price=%u shares=%u\n",
               (unsigned long long)f.timestamp_ns, f.side, f.price_raw, f.shares);
        if (f.side == 'B') total_bid_fill_shares += f.shares;
    }
    printf("total bid-side filled shares = %u (quote_size cap = %u)\n",
           total_bid_fill_shares, p.quote_size);
    return 0;
}
