#pragma once
#include "itch_parser.hpp"
#include "order_book.hpp"  // OrderRecord, PriceLevel, TopOfBook
#include <cstdint>
#include <deque>
#include <unordered_map>
#include <vector>

// FIFO queue-aware order book.
// Plan: .claude/plans/avellaneda-stoikov-mm-sim.md, step 1.
//
// Same public contract as OrderBookFlat PLUS per-level FIFO order queues so
// price-time priority is ground truth: the MM simulator's shadow order gets
// a real position in the real queue. top_of_book() matches OrderBookFlat
// exactly on any message sequence (parity test pins this).
//
// Representation: per side, a flat vector<deque<QueueEntry>> indexed by price
// tick (like OrderBookFlat's level array) holding the FIFO queue at each
// level, a parallel vector<uint32_t> of level share totals for O(1)
// top-of-book, and an order_ref -> (side, tick) locator. Executions and
// deletes find their entry by scanning the (short) level deque.

namespace itch {

class OrderBookQueue {
public:
    struct QueueEntry {
        uint64_t order_ref;
        uint32_t shares;
    };

    OrderBookQueue(uint32_t min_price_raw, uint32_t max_price_raw,
                   uint32_t tick_size = 1);

    // Same mutation API as OrderBookFlat (visitor-compatible).
    void add(uint64_t order_ref, char side, uint32_t price_raw, uint32_t shares);
    uint32_t execute(uint64_t order_ref, uint32_t executed_shares);
    bool del(uint64_t order_ref);
    void replace(uint64_t old_ref, uint64_t new_ref, uint32_t shares, uint32_t price_raw);

    TopOfBook top_of_book() const;

    // Queue introspection for the shadow order: FIFO entries at a level (empty
    // when the level is vacant or the price is out of the book's range).
    const std::deque<QueueEntry>& level_queue(char side, uint32_t price_raw) const;

    // Total resting shares at a level (0 out of range) — the shadow order's
    // queue-ahead at placement time.
    uint32_t level_shares(char side, uint32_t price_raw) const;

    // Look up a resting order's side / price / current shares by ref. Returns
    // false if the ref is unknown. Used by the simulator to decide whether a
    // tape event lands at (and ahead of) a shadow order.
    bool locate(uint64_t order_ref, char& side, uint32_t& price_raw,
                uint32_t& shares) const;

    uint64_t error_count() const { return error_count_; }
    std::size_t order_count() const { return loc_.size(); }

private:
    static constexpr std::size_t INVALID = SIZE_MAX;

    struct Loc {
        char side;
        std::size_t idx;
    };

    std::size_t index(uint32_t price_raw) const;

    uint32_t min_price_;
    uint32_t max_price_;
    uint32_t tick_size_;
    uint64_t error_count_ = 0;

    std::unordered_map<uint64_t, Loc> loc_;
    std::vector<std::deque<QueueEntry>> bid_q_;
    std::vector<std::deque<QueueEntry>> ask_q_;
    std::vector<uint32_t> bid_tot_;
    std::vector<uint32_t> ask_tot_;
};

}  // namespace itch

